package com.sathavahana.kalamkari.controller;
import com.sathavahana.kalamkari.domain.Coupon; import com.sathavahana.kalamkari.repository.CouponRepository; import org.springframework.web.bind.annotation.*; import java.math.BigDecimal;
@RestController @RequestMapping("/api/v1/coupons") public class CouponController {private final CouponRepository coupons; public CouponController(CouponRepository c){coupons=c;} @GetMapping("/{code}/validate") public Result validate(@PathVariable String code,@RequestParam BigDecimal subtotal){var c=coupons.findByCode(code).orElseThrow(()->new NotFoundException("Coupon not found"));if(!c.usable(subtotal))throw new IllegalArgumentException("Coupon is not valid");var d=c.discount(subtotal);return new Result(c.getCode(),d.min(subtotal));} public record Result(String code,BigDecimal discount){}}
